export const ReelRequestPreset = {
  original: 'original',
  vertical: 'vertical',
} as const;

/**
 * Cutting pace, enforced as a hard max clip length after curation: fast = 2-6 s clips, normal = up to 15 s, cinematic = up to 40 s. Overlong clips are split at scene boundaries or sentence gaps.
 */
export type ReelRequestPace = typeof ReelRequestPace[keyof typeof ReelRequestPace];


export const ReelRequestPace = {
  fast: 'fast',
  normal: 'normal',
  cinematic: 'cinematic',
} as const;

export interface ReelRequest {
  /**
     * What to highlight, e.g. "the fact about faith"
     * @minLength 3
     */
  prompt: string;
  /**
     * Restrict the reel to one asset, or null/omitted for the whole library
     * @nullable
     */
  media_id?: string | null;
  /**
     * Restrict the reel to a set of assets (e.g. a project's media pool)
     * @nullable
     */
  media_ids?: string[] | null;
  /** @nullable */
  project_id?: string | null;
  /**
     * Desired run time in seconds; the builder selects enough material to reach it (up to 4 hours)
     * @minimum 30
     * @maximum 14400
     * @nullable
     */
  target_duration_seconds?: number | null;
  preset?: ReelRequestPreset;
  burn_captions?: boolean;
  /**
     * Clip cap when no target duration is given
     * @minimum 1
     * @maximum 500
     */
  max_clips?: number;
  /** Cutting pace, enforced as a hard max clip length after curation: fast = 2-6 s clips, normal = up to 15 s, cinematic = up to 40 s. Overlong clips are split at scene boundaries or sentence gaps. */
  pace?: ReelRequestPace;
  /** Select clips and return a draft without rendering; render later via /reels/{id}/render */
  dry_run?: boolean;
}

